    "summary": "汴河两岸的清明时节，一座都城在手卷里慢慢展开。",
    "story": "张择端把北宋东京画成可以走进去的长卷：城门、骆驼队、虹桥上船夫在喊，店铺在招揽。没有英雄站在画面中央，生活本身就是主题。手卷必须从右向左展开，观看变成一场旅行。后来的摹本无数，但原作仍是中国人对城市最深的记忆之一。"
