    "story": "葛饰北斋的这张浮世绘属于《富岳三十六景》。普鲁士蓝让浪壁近乎垂直，三艘渔船被夹在水的缝隙中。远处富士山稳定如印。它本来是可以买回家的版画，后来成为日本视觉的世界名片。浪再高，山仍在——这是一种构图，也是一种脾气。"
