    "story": "《独角兽挂毯》组画里，这一幅常被单独记住：独角兽安坐栅栏中，颈上锁链系着石榴树，背景是密密的千花地。它可能象征爱情被驯服，也可能是基督受难后的宁静。羊毛、丝线与金银线把一座花园织进房间。织物在这里不是软装饰，而是可以悬挂的神学。"
